use std::io;

fn create_pipe() -> io::Result<(RawFd, RawFd)> {
    let mut fds = [0 as libc::c_int; 2];
    unsafe {
        if libc::pipe(fds.as_mut_ptr()) == 0 {
            Ok((fds[0] as RawFd, fds[1] as RawFd))
        } else {
            Err(io::Error::last_os_error())
        }
    }
}

